static void RoundTrip(){var path=Path.Combine(Path.GetTempPath(),$"cosmic-{Guid.NewGuid():N}.dxf");try{var d=new CosmicDesignerDocument();d.AddBend(SectionAxis.W,12,BendDirection.Up);d.AddBend(SectionAxis.W,42,BendDirection.Down);d.UpdateSegment(d.WSegments[0],10);d.AddHole("Circle",30,40);d.AddHole("Hexagon",50,60);d.MicroJoints.Add(new(){Id="MJ001",ParentContourId="OUTER",Position=1.2,Width=.1,Sequence=5});d.WView.Dimensions=false;d.WView.BentMode=true;d.WView.RotationQuarterTurns=3;d.HView.Dimensions=true;d.HView.BentMode=true;d.HView.RotationQuarterTurns=2;d.ChangeThickness(.3);CosmicDxfSerializer.Save(d,path);var text=File.ReadAllText(path,Encoding.ASCII);if(!text.Contains("\r\nL\r\n")||!text.Contains("\r\nV\r\n")||!text.Contains("CIRCLE")||!text.Contains("COSMIC_DESIGNER_JSON:")||!text.Contains("\r\n5\r\n"))Fail("DXF layers/metadata/units");var r=CosmicDxfSerializer.Load(path);Eq(.3,r.Material.Thickness);if(r.Bends.Count!=2||r.Cuts.Count!=2||r.InnerContours.Count!=2||r.MicroJoints.Count!=1||r.WSegments.Count!=3)Fail("metadata roundtrip");Eq(0,r.WSegments[0].Index);Eq(1,r.WSegments[1].Index);Eq(10,r.WSegments[0].Length);if(r.Cuts[1].Shape!="Hexagon"||r.Cuts[1].Geometry.Count!=6)Fail("hole roundtrip");if(r.WView.Dimensions||!r.WView.BentMode||r.WView.RotationQuarterTurns!=3||!r.HView.Dimensions||!r.HView.BentMode||r.HView.RotationQuarterTurns!=2)Fail("section view state roundtrip");}finally{if(File.Exists(path))File.Delete(path);}}
static void GeneralDxfImport(){var path=Path.Combine(Path.GetTempPath(),$"import-{Guid.NewGuid():N}.dxf");var saved=path+".saved.dxf";try{var pairs=new[]{(0,"SECTION"),(2,"ENTITIES"),(0,"LINE"),(8,"-L-"),(10,"10"),(20,"20"),(11,"110"),(21,"20"),(0,"LINE"),(8,"L"),(10,"110"),(20,"20"),(11,"110"),(21,"70"),(0,"LINE"),(8,"L"),(10,"110"),(20,"70"),(11,"10"),(21,"70"),(0,"LINE"),(8,"L"),(10,"10"),(20,"70"),(11,"10"),(21,"20"),(0,"CIRCLE"),(8,"L"),(10,"40"),(20,"40"),(40,"5"),(0,"LINE"),(8,"V"),(10,"35"),(20,"20"),(11,"35"),(21,"70"),(0,"LINE"),(8,"-V1-"),(10,"10"),(20,"55"),(11,"110"),(21,"55"),(0,"ENDSEC"),(0,"EOF")};File.WriteAllText(path,string.Join("\r\n",pairs.SelectMany(x=>new[]{x.Item1.ToString(),x.Item2}))+"\r\n",Encoding.ASCII);if(CosmicDxfSerializer.HasMetadata(path))Fail("plain DXF metadata detection");var result=GeneralDxfImportEngine.Import(path);Eq(10,result.Document.Material.Width);Eq(5,result.Document.Material.Height);Eq(.2,result.Document.Material.Thickness);if(result.Document.OuterContour.Segments.Count!=4||result.Document.Cuts.Count!=1||result.Document.Bends.Count!=2)Fail("general DXF import counts");if(result.Document.Bends.Count(x=>x.Axis==SectionAxis.W)!=1||result.Document.Bends.Count(x=>x.Axis==SectionAxis.H)!=1)Fail("general DXF bend axes");CosmicDxfSerializer.Save(result.Document,saved);var loaded=CosmicDxfSerializer.Load(saved);if(loaded.Cuts.Single().Geometry.Single() is not CircleSegment||loaded.OuterContour.Segments.Count!=4)Fail("imported geometry metadata roundtrip");Eq(10,loaded.Material.Width);}finally{if(File.Exists(path))File.Delete(path);if(File.Exists(saved))File.Delete(saved);}}
static void FlatMaterialMask(){var d=new CosmicDesignerDocument();d.AddHole("Circle",150,150);var transform=new FlatViewportTransform(1,new(0,300));var mask=FlatMaterialMaskEngine.Build(d,transform);if(!mask.FillContains(transform.ToScreen(new(10,10)))||mask.FillContains(transform.ToScreen(new(150,150)))||mask.FillContains(transform.ToScreen(new(-1,10))))Fail("flat material cut mask");var corner=d.AddHole("Rectangle",290,290);d.UpdateCut(corner,290,290,20,20,7);if(!d.TryMergeBoundaryCut(corner))Fail("flat mask notch fixture");mask=FlatMaterialMaskEngine.Build(d,transform);if(mask.FillContains(transform.ToScreen(new(295,295))))Fail("flat material outer notch mask");}
static void CutSurface(){var d=new CosmicDesignerDocument();var cut=d.AddHole("Circle",150,150);d.UpdateCut(cut,150,150,40,40,7);var mesh=BentSurfaceEngine.Build(d);if(mesh.Triangles.Count==0||mesh.Edges.Count!=28)Fail("3D cut boundary edges");for(var i=0;i<mesh.Triangles.Count;i+=3){var a=mesh.Points[mesh.Triangles[i]];var b=mesh.Points[mesh.Triangles[i+1]];var c=mesh.Points[mesh.Triangles[i+2]];var x=(a.X+b.X+c.X)/3;var y=(a.Y+b.Y+c.Y)/3;if((x-150)*(x-150)+(y-150)*(y-150)<19*19)Fail("3D cut face remained");}}
